#include <stdio.h>

int main() {
    int m[3][3] = {{2, 0, 1}, {4, 5, 6}, {7, 8, 9}};
    int main_diag = 0, anti_diag = 0;
    for (int i = 0; i < 3; i++) {
        main_diag += m[i][i];
        anti_diag += m[i][2 - i];
    }
    printf("Main diagonal: %d\n", main_diag);
    printf("Anti-diagonal: %d\n", anti_diag);
    return 0;
}
